select o_orderkey, sum(l_extendedprice * (1 - l_discount)) as revenue, o_orderdate, o_shippriority from (SELECT "c_custkey" AS c_custkey, "c_name" AS c_name, "c_address" AS c_address, "c_nationkey" AS c_nationkey, "c_phone" AS c_phone, "c_acctbal" AS c_acctbal, "c_mktsegment" AS c_mktsegment, "c_comment" AS c_comment, "c_orders.o_orderkey" AS o_orderkey, "c_orders.o_orderstatus" AS o_orderstatus, "c_orders.o_totalprice" AS o_totalprice, "c_orders.o_orderdate" AS o_orderdate, "c_orders.o_orderpriority" AS o_orderpriority, "c_orders.o_clerk" AS o_clerk, "c_orders.o_shippriority" AS o_shippriority, "c_orders.o_comment" AS o_comment, "c_orders.o_lineitems.l_partkey" AS l_partkey, "c_orders.o_lineitems.l_suppkey" AS l_suppkey, "c_orders.o_lineitems.l_linenumber" AS l_linenumber, "c_orders.o_lineitems.l_quantity" AS l_quantity, "c_orders.o_lineitems.l_extendedprice" AS l_extendedprice, "c_orders.o_lineitems.l_discount" AS l_discount, "c_orders.o_lineitems.l_tax" AS l_tax, "c_orders.o_lineitems.l_returnflag" AS l_returnflag, "c_orders.o_lineitems.l_linestatus" AS l_linestatus, "c_orders.o_lineitems.l_shipdate" AS l_shipdate, "c_orders.o_lineitems.l_commitdate" AS l_commitdate, "c_orders.o_lineitems.l_receiptdate" AS l_receiptdate, "c_orders.o_lineitems.l_shipinstruct" AS l_shipinstruct, "c_orders.o_lineitems.l_shipmode" AS l_shipmode, "c_orders.o_lineitems.l_comment" AS l_comment FROM read_parquet_flat('nestedcustomer.parquet'))
where c_mktsegment = 'BUILDING' and o_orderdate < date '1995-03-15' and l_shipdate > date '1995-03-15'
group by o_orderkey, o_orderdate, o_shippriority order by revenue desc, o_orderdate limit 10
